    if wall_row is not None:
        toward_up = wall_row == 0
    else:
        wall_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
        toward_up = False
        if wall_col is None:
            return [row[:] for row in grid]
        # Horizontal gravity when the wall is a full-height column.
        toward_left = wall_col == 0
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            objects.append((color, cells))
    result = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                result[r][c] = 2
    # Pack each rigid object toward the wall, nearest objects first.
