        objects.sort(key=lambda obj: min(r for r,c in obj[1]), reverse=not toward_up)
        for color, cells in objects:
            while True:
                dr = -1 if toward_up else 1
                shifted = [(r+dr,c) for r,c in cells]
                if any(r < 0 or r >= h or c < 0 or c >= w or result[r][c] != 0 for r,c in shifted):
                    break
                cells = shifted
            for r,c in cells:
                result[r][c] = color
    else:
        objects.sort(key=lambda obj: min(c for r,c in obj[1]), reverse=not toward_left)
        for color, cells in objects:
            while True:
                dc = -1 if toward_left else 1
                shifted = [(r,c+dc) for r,c in cells]
                if any(r < 0 or r >= h or c < 0 or c >= w or result[r][c] != 0 for r,c in shifted):
